async function mount(page:Page,kind:string,props:unknown){await page.goto(origin+'/fixture');await page.waitForFunction(()=>!!(window as unknown as {ready:boolean}).ready);await page.evaluate(({kind,props})=>(window as unknown as {mountUI:(k:string,p:unknown)=>void}).mountUI(kind,props),{kind,props});await page.waitForSelector('main > *');await page.waitForFunction(()=>!!(window as unknown as {uiMounted:boolean}).uiMounted);}
const controlledPages=new WeakSet<Page>();
async function scene(page:Page,props:typeof initial=initial){let current=props.initialClips,next=props.initialVideo;await page.route('**/api/trpc/clip.list?*',r=>r.fulfill({json:result({clips:current})}));await page.route('**/api/trpc/video.get?*',r=>r.fulfill({json:result(next)}));await mount(page,'detail',props);if(!controlledPages.has(page)){await page.clock.install();await page.clock.resume();controlledPages.add(page);}return {setClips:(value:ClipScreen[])=>{current=value;},setVideo:(value:VideoScreen)=>{next=value;},tick:async()=>{const responses=Promise.all(['video.get?','clip.list?'].map(part=>page.waitForResponse(r=>r.url().includes(part))));await page.clock.runFor(5100);await Promise.all((await responses).map(r=>r.finished()));await page.evaluate(()=>new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve()))));}};}
async function preferences(page:Page,theme:string,layout:string){const settings=page.locator('.workspace-settings');if(!await settings.evaluate((n:HTMLDetailsElement)=>n.open))await settings.locator('summary').click();await page.getByLabel('Компоновка').selectOption(layout);const toggle=page.getByRole('button',{name:'Светлая тема',exact:true});if((await toggle.getAttribute('aria-pressed')==='true')!==(theme==='light'))await toggle.click();await settings.locator('summary').click();}
async function more(page:Page){const el=page.locator('.clip-card[data-selected=true] .clip-secondary');if(!await el.evaluate((n:HTMLDetailsElement)=>n.open))await el.locator(':scope > summary').click();}
async function edit(page:Page){await more(page);await page.getByRole('button',{name:'Изменить оформление',exact:true}).click();}
async function share(page:Page){await more(page);await page.getByRole('button',{name:'Поделиться',exact:true}).click();}
async function stats(page:Page,base=partner){let ensure=0;await page.route('**/api/trpc/partner.ensurePersonalLink',r=>{ensure++;return r.fulfill({json:result(base.codes[0])});});await page.route('**/api/trpc/partner.dashboard?*',r=>r.fulfill({json:result(r.request().url().includes('code_id')?{...base,codes:[base.codes[1]],counters:{...counters,visits:3}}:base)}));await mount(page,'partner',{personal:true,presentation:'statistics',publicOrigin:'https://test.invalid'});await poll(()=>page.locator('#personal-blogger-url').inputValue()).toContain('/r/oldest');return ()=>ensure;}

