    for(let index=0;index<6;index++){const email=`qa-${index}-${schema}@test.invalid`,token=await auth.register(email,'Synthetic-UI-password-2026!','198.51.100.0/24');tokens.push(token);ids.push((await auth.authenticate(token))!.account_id);}
